import os
import torch


class Config:
    """
    Global configuration for the SCSL-Net (Split-Context Shared-Latent Network)
    solution for Pulmonary Fibrosis Progression prediction.
    """

    # =========================================================================
    # 1. File Paths and Directories
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Metadata files generated by the metadata script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Caching directory for Idea 57 (SCSL-Net)
    # Used to store processed Tri-Slab numpy arrays to speed up training
    IDEA_ID = "idea_57"
    CACHE_DIR = os.path.join(WORKING_DIR, IDEA_ID)

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # 2. Data Preprocessing & Augmentation
    # =========================================================================
    # Resolution: 224x224 matches EfficientNet-B0 native resolution
    IMG_SIZE = 224

    # Tri-Slab configuration: 3 slabs per view (Axial/Coronal)
    NUM_SLABS = 3

    # Normalization constants (ImageNet defaults)
    IMAGENET_MEAN = [0.485, 0.456, 0.406]
    IMAGENET_STD = [0.229, 0.224, 0.225]

    # Tabular features used for the Shared Latent Encoder
    # Note: 'Weeks' is NOT included here; it is used in the parametric trajectory equation.
    TABULAR_COLS = ["Age", "Sex", "SmokingStatus", "Percent"]

    # =========================================================================
    # 3. Model Architecture (SCSL-Net)
    # =========================================================================
    BACKBONE = "efficientnet-b0"
    PRETRAINED = True

    # Dimensionality Constraints
    BACKBONE_DIM = 1280  # Output dim of EfficientNet-B0 (without projection)
    LATENT_DIM = 128  # Shared Latent Vector (T_lat) - Clinical Prior
    ALIGN_DIM = 1280  # Projected Tabular dim for Attention (T_align)
    CONTEXT_DIM = 64  # Compressed Context Stream dim (H_vis, H_ctx)

    # The final concatenated vector will be:
    # 64 (Visual Context) + 64 (Tabular Context) + 128 (Clinical Prior) = 256 dim

    # =========================================================================
    # 4. Training Hyperparameters
    # =========================================================================
    SEED = 42

    # Batch size (A100 has 40GB, allowing reasonable batch sizes)
    BATCH_SIZE = 32

    # Optimization
    EPOCHS = 50
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS
    ETA_MIN = 1e-6

    # Early Stopping
    PATIENCE = 7  # Strict patience to prevent overfitting on small data

    # Metric / Loss Configuration
    MAX_ERROR = 1000  # Threshold for absolute error in metric
    CONFIDENCE_CLIP = 70  # Minimum confidence value

    # =========================================================================
    # 5. Compute & Runtime
    # =========================================================================
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Debugging flags
    DEBUG = False  # Set to True to train on a small subset
    DEBUG_SAMPLE_SIZE = 50  # Number of samples to use if DEBUG is True

    @classmethod
    def setup(cls):
        """
        Creates necessary directories and sets reproducibility seeds.
        Call this at the start of the main execution.
        """
        # Create directories
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        import random
        import numpy as np

        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(cls.SEED)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
